mapper.select:

select CHOOSEID,PERIOD,MARKETNAME,PRODUCTNAME,USERUNIQUE,CHOOSEVALUE,GROUPNAME from chooseorder
where USERUNIQUE=#{userUnique}
  and PERIOD=(select CURRENTPERIOD from gamegroupmember where USERUNIQUE=#{userUnique})
  and CHOOSEVALUE<#{orderIncrement}

mapper.update:
update  chooseorder
set CHOOSEVALUE=CHOOSEVALUE+#{chooseValue}
where USERUNIQUE=#{userUnique}
  and PERIOD=(select CURRENTPERIOD from gamegroupmember where USERUNIQUE=#{userUnique})

mapper.select:
select count(*) from chooseorder
where USERUNIQUE=#{userUnique}
  and PERIOD=#{period}
  and MARKETNAME=#{marketName}
  and PRODUCTNAME=#{productName}
  and GROUPNAME=#{groupName}

mapper.delete:
delete from chooseorder
where PERIOD=#{period}
  and MARKETNAME=#{marketName}
  and PRODUCTNAME=#{productName}
  and GROUPNAME=#{groupName}
  and not exists (
      select 1
      from adofuser
      where adofuser.USERUNIQUE = chooseorder.USERUNIQUE
        and adofuser.PERIOD = chooseorder.PERIOD
        and adofuser.MARKETNAME = chooseorder.MARKETNAME
        and adofuser.PRODUCTNAME = chooseorder.PRODUCTNAME
        and adofuser.MONEY > 0
  )
